async function openGroupMatch(){return openMatchBuilder()}
function openMatchBuilder(initialTxId=null,seedActionId=null){
  if(!state.transactions.length)return toast('There are no unreconciled bank transactions to match.');
  const seed=seedActionId?state.smartActions.get(seedActionId)?.match:null,initial=state.transactions.find(x=>String(x.id)===String(initialTxId))||seed?.bankRows?.[0]||state.transactions[0],direction=Math.sign(initial.amount),currency=String(initial.bank_accounts?.currency||'NZD').toUpperCase();
  const builder={id:`builder:${crypto.randomUUID()}`,businessId:businessId(),direction,currency,bankIds:new Set((seed?.bankRows||[initial]).map(x=>String(x.id))),records:new Map(),requestId:crypto.randomUUID(),search:''};
  if(seed){const totals=new Map();for(const a of seed.allocations||[]){const r=seed.records.find(x=>String(x.id)===String(a.invoice_id||a.expense_id)&&String(x.paymentId||'')===String(a.existing_customer_payment_id||a.existing_expense_payment_id||''));if(r)totals.set(recordKey(r),(totals.get(recordKey(r))||0)+cents(a.amount))}for(const r of seed.records)builder.records.set(recordKey(r),{record:r,amount:totals.get(recordKey(r))||cents(r.available)})}
  state.matchBuilder=builder;openModal('<div id="brSmartBuilder"></div>');renderMatchBuilder()
}
