  $('brBuilderCancel').onclick=()=>{$('bankReconModal').classList.remove('open');state.matchBuilder=null};
  $('brBuilderSearch').oninput=e=>{b.search=e.target.value;clearTimeout(renderMatchBuilder._search);renderMatchBuilder._search=setTimeout(renderMatchBuilder,180)};
