  const sync=()=>{const selected=[...document.querySelectorAll('[data-stripe-payout-id]:checked')],total=selected.reduce((a,x)=>a+num(x.dataset.stripePayoutAmount),0),ok=Math.abs(total-num(tx.amount))<=0.01;$('brStripePayoutTotal').textContent=`Selected: ${money(total)}${ok?' · matches bank payout':` · remaining ${money(num(tx.amount)-total)}`}`;$('brStripePayoutSave').disabled=!ok};
  document.querySelectorAll('[data-stripe-payout-id]').forEach(x=>x.onchange=sync);
